1	// Rational-number library implemented with plain Number arithmetic
2	// (numerator/denominator pairs + gcd). BigInt is intentionally not used.
3	
4	function gcd(a, b) {
5	  a = Math.abs(a);
6	  b = Math.abs(b);
7	  while (b !== 0) {
8	    const t = b;
9	    b = a % b;
10	    a = t;
11	  }
12	  return a;
13	}
14	
15	export class Fraction {
16	  constructor(numerator, denominator = 1) {
17	    if (denominator === 0) {
18	      throw new Error('ZeroDivisionError: Fraction(' + numerator + ', 0)');
19	    }
20	    let num = numerator;
21	    let den = denominator;
22	    // Keep the sign on the numerator; denominator is always positive.
23	    if (den < 0) {
24	      num = -num;
25	      den = -den;
26	    }
27	    const g = gcd(num, den);
28	    this.num = num / g;
29	    this.den = den / g;
30	  }
31	
32	  static fromInt(n) {
33	    return new Fraction(n, 1);
34	  }
35	
36	  add(other) {
37	    return new Fraction(this.num * other.den + other.num * this.den,
38	      this.den * other.den);
39	  }
40	
41	  mul(other) {
42	    return new Fraction(this.num * other.num, this.den * other.den);
43	  }
44	
45	  div(other) {
46	    return new Fraction(this.num * other.den, this.den * other.num);
47	  }
48	
49	  reciprocal() {
50	    return new Fraction(this.den, this.num);
51	  }
52	
53	  gt(other) {
54	    return this.num * other.den > other.num * this.den;
55	  }
56	
57	  toString() {
58	    return this.den === 1 ? `${this.num}` : `${this.num}/${this.den}`;
59	  }
60	}

1	// cli.mjs — argparse-style command-line parser for six required integer options.
2	// Pure Node.js ESM, zero dependencies.
3	
4	const OPTION_NAMES = ['a', 'b', 'c', 'd', 'e', 'f'];
5	
6	function usageLine(progName) {
7	  return `usage: ${progName} [-h] --a A --b B --c C --d D --e E --f F`;
8	}
9	
10	function errorExit(progName, message) {
11	  process.stderr.write(usageLine(progName) + '\n');
12	  process.stderr.write(`${progName}: error: ${message}\n`);
13	  process.exit(2);
14	}
15	
16	function printHelp(progName) {
17	  const lines = [
18	    usageLine(progName),
19	    '',
20	    'options:',
21	    '  -h, --help  show this help message and exit',
22	  ];
23	  for (const name of OPTION_NAMES) {
24	    const upper = name.toUpperCase();
25	    lines.push(`  --${name} ${upper}`);
26	  }
27	  process.stdout.write(lines.join('\n') + '\n');
28	  process.exit(0);
29	}
30	
31	// Mimic Python int(): optional surrounding whitespace, optional +/- sign, then digits.
32	const INT_PATTERN = /^\s*[+-]?\d+\s*$/;
33	
34	function parseIntArg(progName, optionFlag, raw) {
35	  if (!INT_PATTERN.test(raw)) {
36	    errorExit(progName, `argument ${optionFlag}: invalid int value: '${raw}'`);
37	  }
38	  return parseInt(raw, 10);
39	}
40	
41	export function parseArgs(argv, progName) {
42	  const values = {};
43	  const extras = [];
44	
45	  let i = 0;
46	  while (i < argv.length) {
47	    const token = argv[i];
48	
49	    if (token === '-h' || token === '--help') {
50	      printHelp(progName);
51	    }
52	
53	    let name = null;
54	    let inlineValue = null;
55	
56	    if (token.startsWith('--')) {
57	      const eq = token.indexOf('=');
58	      if (eq !== -1) {
59	        name = token.slice(2, eq);
60	        inlineValue = token.slice(eq + 1);
61	      } else {
62	        name = token.slice(2);
63	      }
64	    }
65	
66	    if (name !== null && OPTION_NAMES.includes(name)) {
67	      let raw;
68	      if (inlineValue !== null) {
69	        raw = inlineValue;
70	      } else {
71	        if (i + 1 >= argv.length) {
72	          errorExit(progName, `argument --${name}: expected one argument`);
73	        }
74	        raw = argv[i + 1];
75	        i += 1;
76	      }
77	      values[name] = parseIntArg(progName, `--${name}`, raw);
78	    } else {
79	      extras.push(token);
80	    }
81	
82	    i += 1;
83	  }
84	
85	  if (extras.length > 0) {
86	    errorExit(progName, `unrecognized arguments: ${extras.join(' ')}`);
87	  }
88	
89	  const missing = OPTION_NAMES.filter((n) => !(n in values));
90	  if (missing.length > 0) {
91	    errorExit(
92	      progName,
93	      `the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`
94	    );
95	  }
96	
97	  return {
98	    a: values.a,
99	    b: values.b,
100	    c: values.c,
101	    d: values.d,
102	    e: values.e,
103	    f: values.f,
104	  };
105	}

