// test20.mjs — Node.js (ESM) port of test20.py.
// Depends only on ./fraction.mjs and ./cli.mjs (zero external deps).

import { Fraction } from './fraction.mjs';
import { parseArgs } from './cli.mjs';

const args = parseArgs(process.argv.slice(2), 'test20.mjs');

const f1 = new Fraction(args.a, args.b);
console.log(f1.toString());
const f2 = new Fraction(args.c, args.d);
console.log(f2.toString());
const f3 = new Fraction(args.e, args.f);
console.log(f3.toString());

const sum1 = f1.add(f2);
console.log(sum1.toString());
const sum2 = sum1.add(f3);
console.log(sum2.toString());

const product1 = f1.mul(f2);
console.log(product1.toString());
const product2 = product1.mul(f3);
console.log(product2.toString());

// harmonic_mean = 3 / (1/f1 + 1/f2 + 1/f3)
const harmonicMean = Fraction.fromInt(3).div(
  f1.reciprocal().add(f2.reciprocal()).add(f3.reciprocal())
);
console.log(harmonicMean.toString());

// arithmetic_mean = (f1 + f2 + f3) / 3
const arithmeticMean = f1.add(f2).add(f3).div(Fraction.fromInt(3));
console.log(arithmeticMean.toString());

// Print booleans in Python style: "True"/"False"
console.log(f1.gt(f2) ? 'True' : 'False');
console.log(f2.gt(f3) ? 'True' : 'False');
